const big = Array.from({length: 100000}, (_, i) => i);
let linearSteps = 0;
for (let i = 0; i < big.length; i++) {
  linearSteps++;
  if (big[i] === 99999) break;
}
console.log('linear steps:', linearSteps);
let low = 0, high = big.length - 1, binarySteps = 0;
while (low <= high) {
  binarySteps++;
  const mid = Math.floor((low + high) / 2);
  if (big[mid] === 99999) break;
  if (big[mid] < 99999) low = mid + 1;
  else high = mid - 1;
}
console.log('binary steps:', binarySteps);

